package com.autocare.platform.order;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;

class JdbcExperienceDetailTest extends JdbcServiceArchiveTest {
 ExperienceModeration service;long cardId;
 String approved(){models();cardId=awaiting();service=moderation(true);service.moderate(operator(),cardId,key(),decision(1,true));return jdbc.queryForObject("SELECT public_id FROM experience_card_moderation WHERE card_id=?",String.class,cardId);}
 int status(Runnable r){return assertThrows(ResponseStatusException.class,r::run).getStatusCode().value();}
 void unavailable(String id){assertEquals(404,status(()->service.experience(other,2,id)));assertTrue(((List<?>)service.experiences(other,2,null).get("items")).isEmpty());}
 @Test void detailReusesExactApprovedProjectionAndHasNoReadSideEffects(){String id=approved();int audits=count("audit_log"),keys=count("idempotency_record"),cards=count("experience_card"),reviews=count("experience_card_moderation");var detail=db.mapper.valueToTree(service.experience(other,2,id));var listed=db.mapper.valueToTree(service.experiences(other,2,null)).path("items").get(0);assertEquals(Set.of("vehicle_id","experience"),db.mapper.convertValue(detail,Map.class).keySet());assertEquals(2,detail.path("vehicle_id").asInt());assertEquals(listed,detail.path("experience"));for(String field:List.of("order_id","archive_id","card_id","user_id","file_id","phone","vin","plate","object_key"))assertFalse(detail.toString().contains("\""+field+"\""));assertEquals(audits,count("audit_log"));assertEquals(keys,count("idempotency_record"));assertEquals(cards,count("experience_card"));assertEquals(reviews,count("experience_card_moderation"));}
 @Test void withdrawingAndReapprovingCreatesNewReferenceAndNeverRevivesOldOne(){String old=approved();cards().change(owner,cardId,key(),db.mapper.createObjectNode(),false);unavailable(old);cards().change(owner,cardId,key(),consent(),true);assertEquals(404,status(()->service.experience(other,2,old)));int revision=jdbc.queryForObject("SELECT revision FROM experience_card",Integer.class);service.moderate(operator(),cardId,key(),decision(revision,true));String next=jdbc.queryForObject("SELECT public_id FROM experience_card_moderation ORDER BY id DESC LIMIT 1",String.class);assertNotEquals(old,next);assertEquals(404,status(()->service.experience(other,2,old)));assertEquals(next,((Map<?,?>)service.experience(other,2,next).get("experience")).get("experience_id"));}
 @Test void recipientOwnershipModelDeletionAndRandomIdsCannotSelectPrivateRecords(){String id=approved();assertEquals(404,status(()->service.experience(owner,2,id)));assertEquals(404,status(()->service.experience(other,2,key())));jdbc.update("UPDATE vehicle SET model_id=2 WHERE id=2");unavailable(id);jdbc.update("UPDATE vehicle SET model_id=NULL WHERE id=2");unavailable(id);jdbc.update("UPDATE vehicle SET model_id=1,user_id=1 WHERE id=2");assertEquals(404,status(()->service.experience(other,2,id)));jdbc.update("UPDATE vehicle SET user_id=2,is_deleted=1 WHERE id=2");assertEquals(404,status(()->service.experience(other,2,id)));}
 @Test void inactiveAndDeletedModelSeriesOrBrandHideBothProjections(){String id=approved();for(String table:List.of("model","series","brand")){jdbc.update("UPDATE `"+table+"` SET status=0 WHERE id=1");unavailable(id);jdbc.update("UPDATE `"+table+"` SET status=1,is_deleted=1 WHERE id=1");unavailable(id);jdbc.update("UPDATE `"+table+"` SET is_deleted=0 WHERE id=1");assertDoesNotThrow(()->service.experience(other,2,id));}}
 @Test void changedSourceUnsafeFilesAndTamperedSummaryDenyDetail(){String id=approved();jdbc.update("UPDATE technician_report SET repair_plan='changed source'");unavailable(id);jdbc.update("UPDATE technician_report SET repair_plan='检查与清洁'");jdbc.update("UPDATE file_object SET scan_status='INFECTED' WHERE id=101");unavailable(id);jdbc.update("UPDATE file_object SET scan_status='CLEAN' WHERE id=101");jdbc.update("UPDATE experience_card SET summary=JSON_SET(summary,'$.work_minutes',999)");unavailable(id);}
 @Test void sourceOwnerAndVehicleMustRemainCurrent(){String id=approved();for(String update:List.of("UPDATE vehicle SET is_deleted=1 WHERE id=1","UPDATE vehicle SET user_id=2 WHERE id=1","UPDATE vehicle SET model_id=2 WHERE id=1","UPDATE user SET status=2 WHERE id=1")){jdbc.update(update);unavailable(id);jdbc.update("UPDATE vehicle SET is_deleted=0,user_id=1,model_id=1 WHERE id=1");jdbc.update("UPDATE user SET status=1 WHERE id=1");}}
 @Test void disabledPublicationRevokedSessionAndInactiveRecipientFailClosed(){String id=approved();assertEquals(503,status(()->moderation(false).experience(other,2,id)));assertTrue(((List<?>)moderation(false).experiences(other,2,null).get("items")).isEmpty());jdbc.update("UPDATE user SET status=2 WHERE id=2");assertEquals(401,status(()->service.experience(other,2,id)));jdbc.update("UPDATE user SET status=1 WHERE id=2");jdbc.update("UPDATE auth_session SET revoked_at=UTC_TIMESTAMP() WHERE id=?",other.session());assertEquals(401,status(()->service.experience(other,2,id)));}
}
